import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  // Calculate aspect ratio from atlas region (512x320 pixels)
  const aspectRatio = 512 / 320;

  // Define plane dimensions in world units
  const width = 0.8;
  const height = width / aspectRatio;

  // Create plane geometry
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load texture from imageUrl
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material with texture
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    toneMapped: false,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement from config
  const position = config.position || [-3.2, -0.3, 0];
  const rotation = config.rotation || [0, 0, 0];
  const scale = config.scale || [1, 1, 1];

  mesh.position.set(...position);
  mesh.rotation.set(...rotation);
  mesh.scale.set(...scale);

  // Setup cleanup function
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  return mesh;
}
